mapper.select:
SELECT COUNT(1)
FROM learning_rumination_graph_history
WHERE user_id = #{userId}
  AND wordbook_id = #{wordbookId}
  AND scenario_code = #{scenarioCode}
  AND graph_version = #{graphVersion}
  AND deleted = 0

SELECT id
FROM learning_rumination_graph_history
WHERE user_id = #{userId}
  AND wordbook_id = #{wordbookId}
  AND scenario_code = #{scenarioCode}
  AND deleted = 0
ORDER BY graph_version DESC, id DESC
LIMIT 1000 OFFSET #{keepCount}
